# Lightweight in-process abuse guard for the demo MVP. This is not a replacement
# for a shared rate limiter/WAF in production and resets when the process restarts.
_RATE_LIMIT = int(os.getenv("API_RATE_LIMIT_PER_MINUTE", "30"))
_rate_buckets: dict[str, deque[float]] = defaultdict(deque)
_rate_lock = Lock()
_RATE_LIMITED_PATHS = {"/api/chat", "/api/research", "/api/model-check", "/api/document", "/api/feedback"}


@app.middleware("http")
async def add_security_headers(request, call_next):
    """Add baseline browser security headers and a small in-process abuse guard."""
    if request.method == "POST" and request.url.path in _RATE_LIMITED_PATHS:
        client_host = request.client.host if request.client else "unknown"
        now = time.monotonic()
        with _rate_lock:
            bucket = _rate_buckets[client_host]
            while bucket and now - bucket[0] >= 60:
                bucket.popleft()
            if len(bucket) >= max(1, _RATE_LIMIT):
                from fastapi.responses import JSONResponse
                response = JSONResponse({"detail": "Too many requests. Please wait a minute and try again."}, status_code=429)
                response.headers["Retry-After"] = "60"
                response.headers["X-Request-ID"] = uuid.uuid4().hex
                response.headers["X-Content-Type-Options"] = "nosniff"
                response.headers["X-Frame-Options"] = "DENY"
                response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
                response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
                response.headers["Cross-Origin-Opener-Policy"] = "same-origin"
                return response
            bucket.append(now)
    response = await call_next(request)
    # Correlation ID is generated by the server; caller-supplied IDs are not trusted.
    response.headers["X-Request-ID"] = uuid.uuid4().hex
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
    response.headers["Cross-Origin-Opener-Policy"] = "same-origin"
    return response
# Set ALLOWED_ORIGINS to a comma-separated list for cross-origin deployments.
# Same-origin browser use does not require CORS.
_allowed_origins = [x.strip() for x in os.getenv("ALLOWED_ORIGINS", "").split(",") if x.strip()]
if _allowed_origins:
    app.add_middleware(CORSMiddleware, allow_origins=_allowed_origins, allow_methods=["GET", "POST"], allow_headers=["Content-Type", "Authorization"])



# SQLite is used for optional feedback only. Chat messages and PDFs are not stored.
def _feedback_storage_enabled() -> bool:
    """Feedback persistence is opt-in; disable by default on ephemeral hosts."""
    return os.getenv("ENABLE_FEEDBACK_STORAGE", "false").strip().lower() in {"1", "true", "yes", "on"}

def _database_path() -> str:
    return os.getenv("DATABASE_PATH", "vishwa_ai.db").strip() or "vishwa_ai.db"

def _postgres_dsn() -> str:
    """Read an optional managed PostgreSQL URL without exposing it to API responses."""
    return os.getenv("DATABASE_URL", "").strip()

def _database_engine() -> str:
    dsn = _postgres_dsn()
    return "postgresql" if dsn.startswith(("postgres://", "postgresql://")) else "sqlite"

def _connect_db():
    """Connect to managed PostgreSQL when DATABASE_URL is set, otherwise local SQLite."""
    dsn = _postgres_dsn()
    if dsn:
        if not dsn.startswith(("postgres://", "postgresql://")):
            raise ValueError("DATABASE_URL must use postgres:// or postgresql://")
        # Import lazily so local SQLite development does not require a running DB.
        import psycopg
        connection = psycopg.connect(dsn, connect_timeout=5)
        try:
            connection.execute("CREATE TABLE IF NOT EXISTS feedback (id BIGSERIAL PRIMARY KEY, category TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL)")
            connection.commit()
        except Exception:
            connection.close()
            raise
        return connection

    path = _database_path()
    if path != ":memory:":
        Path(path).expanduser().parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path, timeout=5)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA busy_timeout = 5000")
    connection.execute("CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, category TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL)")
    connection.commit()
    return connection

@contextmanager
def _db_connection():
    connection = _connect_db()
    try:
        yield connection
    finally:
        connection.close()

