def _provider_config():
    """Read and validate provider settings without ever returning the API key."""
    base_url = os.getenv("AI_BASE_URL", "").strip().rstrip("/")
    api_key = os.getenv("AI_API_KEY", "").strip()
    model = os.getenv("AI_MODEL", "").strip()
    if not (base_url and api_key and model):
        return None, "missing"
    try:
        parsed = urlsplit(base_url)
        # HTTPS is required for remote providers. Plain HTTP is allowed only for
        # loopback/local Ollama-style endpoints used during local development.
        local_hosts = {"localhost", "127.0.0.1", "::1"}
        if not parsed.hostname or parsed.username or parsed.password or parsed.query or parsed.fragment:
            return None, "invalid_url"
        if parsed.scheme != "https" and not (parsed.scheme == "http" and parsed.hostname.lower() in local_hosts):
            return None, "invalid_url"
        if parsed.scheme not in {"http", "https"}:
            return None, "invalid_url"
        # Avoid accidentally appending the endpoint twice. Configure the API base
        # path, for example https://provider.example/v1, not /chat/completions.
        if parsed.path.rstrip("/").endswith("/chat/completions"):
            return None, "invalid_url"
    except ValueError:
        return None, "invalid_url"
    try:
        timeout = float(os.getenv("AI_TIMEOUT_SECONDS", "45"))
    except ValueError:
        timeout = 45.0
    timeout = min(90.0, max(5.0, timeout))
    return {"base_url": base_url, "api_key": api_key, "model": model, "timeout": timeout}, None

class Message(BaseModel):
    role: Literal["user", "assistant"]
    content: str = Field(min_length=1, max_length=12000)

class ChatRequest(BaseModel):
    message: str = Field(min_length=1, max_length=12000)
    mode: str = "general"
    history: list[Message] = Field(default_factory=list, max_length=20)
    document_context: str = Field(default="", max_length=12000)

class ChatResponse(BaseModel):
    answer: str
    mode: str
    provider: str
    notice: str | None = None

class FeedbackRequest(BaseModel):
    category: Literal["bug", "idea", "other"]
    message: str = Field(min_length=3, max_length=1000)
    consent_to_store: bool = False

class ResearchRequest(BaseModel):
    query: str = Field(min_length=1, max_length=400)

